select (select count(*) from pg_tables where schemaname = 'public') as db_public_tables,
       (to_regclass('public.learners') is not null)                  as db_has_learners,
       m.version,
       m.name,
       (select string_agg(r.version || '_' || r.name, ', ') from repo r where r.name = m.name) as repo_file_with_same_name,
       (to_jsonb(m) - 'statements' - 'version' - 'name')::text                              as other_columns,
       coalesce(array_length(m.statements, 1), 0)                                         as n_statements,
       md5(coalesce(array_to_string(m.statements, E'\n'), ''))                            as statements_md5,
       left(regexp_replace(coalesce(array_to_string(m.statements, E'\n'), ''), '\s+', ' ', 'g'), 300) as statements_head
  from supabase_migrations.schema_migrations m
 where m.version not in (select version from repo)
 order by m.version;
